private theorem append_left_value {n m : ℕ} (first : Fin n → κ) (second : Fin m → κ)
    (i : Fin (n + m)) (hi : i.val < n) : Fin.append first second i = first ⟨i.val, hi⟩ :=
  Fin.append_left first second ⟨i.val, hi⟩

def code : Code .standard registers := ram[
  two ← #2;
  offset ← #18;
  address ← pointer + offset;
  first ← *address;
  address ← address + two;
  second ← *address;
  if query < first then [ out ← #0 ] else [
    if query < second then [ out ← #1 ] else [ out ← #2 ]
  ] ]

/-- The inclusive rank among two increasing full keys. -/

def result (x : Data registers) : Data registers :=
  let p := x.regs pointer
  let a := x.mem (p + 18)
  let b := x.mem (p + 20)
  (((((((x.set two 2).set offset 18).set address (p + 18)).set first a).set address
    (p + 20)).set second b).set out (rank (x.regs query) a b))

/-- The direct comparison expression equals inclusive rank, with equality counted. -/

private theorem totalDegree_X_le (i : σ) : (X i : MvPolynomial σ K).totalDegree ≤ 1 :=
  (totalDegree_monomial_le _ _).trans (by simp)

/-- Substituting polynomials of degree at most one does not raise the degree. -/

def Term.toCircuit (zero one : C) (t : Term C d) : Circuit (arithSignature C) d 1 :=
  let scale : Formula (arithSignature C) 1 :=
    .gate₂ .mul rfl (.gate (.const t.scale) Fin.elim0) (.input 0)
  scale.toCircuit.comp ((binaryPowerCircuit one d).comp
    (Formula.linearForm zero t.coefficients id).toCircuit)

/-- Term compilation preserves evaluation under any semiring interpretation of the symbols. -/

def notCircuit (C : Circuit σ n 1) : Circuit σ n 1 :=
  ((Circuit.oneGate (σ := signature) Op.not fun _ => 0).mapOp φ).comp C

/-- The circuits `C` and `D` side by side, followed by a gate `op` of two arguments. -/

private theorem wireBitsLe_mono {c : Code} {a b : ℕ} (h : WireBitsLe c a) (hab : a ≤ b) :
    WireBitsLe c b :=
  ⟨fun g hg i hi => (h.1 g hg i hi).trans hab, fun i hi => (h.2 i hi).trans hab⟩

def carries (w : ℕ) : Circuit signature (w + w + 1) ((w + 1) + (w + 1)) :=
  (scan (w + 1) (Nat.clog 2 (w + 1))).comp (initial w)

/-- One sum bit, reading the original inputs followed by the carry network. -/

def zeroPairCircuit (k w : ℕ) : Circuit signature k (w + w) :=
  (Circuit.wiring signature fun _ => 0).comp (Circuit.oneGate (Op.const false) Fin.elim0)

/-- `zeroPairCircuit k w` outputs `false` on every wire. -/

def weightCircuit (k : ℕ) : Circuit signature k (Nat.clog 2 (k + 1)) :=
  let w := Nat.clog 2 (k + 1)
  (Circuit.wiring signature (Fin.castAdd w)).comp
    ((finishCircuit w w).comp (weightPairCircuit k w))

/-- `weightCircuit k` computes the exact binary numeral of `BitString.weight x`. -/

def sumPairs (n w : ℕ) (cs : List (Circuit signature n (w + w))) : Circuit signature n w :=
  (carryLookaheadAdd w).comp (reducePairs n w cs)

/-- Finishing a carry-save word computes its value modulo `2 ^ w`. -/

def muxCircuit (w : ℕ) : Circuit signature (1 + (w + w)) w :=
  (Circuit.pi fun i => (muxBit i).toCircuit).comp
    ((Circuit.id signature _).append (Circuit.oneGate Op.not fun _ => Fin.castAdd (w + w) 0))

def leStep : Circuit signature (1 + 2) 1 :=
  leStepFormula.toCircuit.comp
    ((Circuit.id signature _).append (Circuit.oneGate Op.not fun _ => Fin.natAdd 1 0))

def adjacentDuplicateCircuit {input count k : ℕ} (key : Fin count → Fin k → Fin input) :
    Circuit signature input count :=
  (Circuit.pi fun i : Fin count =>
    ((Formula.input i).or (Formula.input (if h : i.val + 1 < count then ⟨i.val + 1, h⟩
      else ⟨0, by lia⟩))).toCircuit).comp (adjacentEqualityCircuit key)

/-- On sorted keys, adjacent equality detects every repeated key. -/

private theorem EqUpToNeg.isConstOrLiteral (h : EqUpToNeg φ ψ) (hψ : IsConstOrLiteral ψ) :
    IsConstOrLiteral φ :=
  hψ.imp h.isConst fun ⟨i, hi⟩ => ⟨i, h.trans hi⟩

def nandCircuit : Circuit signature 2 1 :=
  (Circuit.oneGate (σ := signature) .not (fun _ => 0)).comp (Circuit.oneGate .and id)

/-- `nandCircuit` computes the NAND of its two input bits. -/

private theorem liftResidue_spec (lower period T K : ℕ) (hp : 0 < period) (hK : lower ≤ K) :
    let v := (liftResidue lower period)^[K] (T % period)
    lower ≤ v ∧ v < lower + period ∧ v % period = T % period := by
  have h := liftResidue_invariant lower period (T % period) K hp (Nat.mod_lt _ hp)
  exact ⟨h.1.elim id (hK.trans ·), h.2⟩

/-- The corrected residue lies in the repeated interval and gives the state at time `T`. -/

private theorem card_basicFeatures_le (n T : ℕ) :
    (basicFeatures (k := k) (State := State) n T).card ≤ featureCount n T k State :=
  (List.toFinset_card_le _).trans (length_basic n T).le

def thresholdCircuitOfMajority (M : Circuit σ (n + (n + 2)) 1) (k : ℕ) : Circuit σ n 1 :=
  M.comp (padCircuit φ n (n + 1 - k))

/-- Whether exactly `k` of the bits are true, from a circuit for majority. -/

def modCircuitOfMajority (q : ℕ) (M : Circuit σ (n + (n + 2)) 1) : Circuit σ n 1 :=
  ((Circuit.oneGate (Unbounded.Op.or (n + 1) : Unbounded.signature.Op) id).mapOp φ).comp
    (Circuit.pi fun k : Fin (n + 1) =>
      if k.val % q ≠ 0 then exactlyCircuitOfMajority φ M k else constCircuit φ false)

def slotEquiv : Fin copies × BitString (ℓ * b) ≃ Fin (copies * 2 ^ (ℓ * b)) :=
  (Equiv.prodCongr (Equiv.refl _) (BitString.equivFin _)).trans finProdFinEquiv

/-- The key of a slot: its copy index followed by its point bits. -/

def pointEquiv (bits : K ≃ BitString b) : (Fin ℓ → K) ≃ BitString (ℓ * b) :=
  (Equiv.arrowCongr (Equiv.refl (Fin ℓ)) bits).trans blocksEquiv.symm

/-- `pointEquiv bits` sends a point to its bits `pointBits bits`. -/

def routedBit (j : ℕ) (i : Fin t) (k : Fin w) (x : BitString (2 * t * (p + w))) : Bool :=
  if first (rank x (pairCopy 0 i)) (rank x (pairCopy 1 i)) j then
    x (finProdFinEquiv (pairCopy 0 i, Fin.natAdd p k))
  else x (finProdFinEquiv (pairCopy 1 i, Fin.natAdd p k))

/-- The gate budget of one disjunctive normal form over the two prefixes of a pair. -/

def subtract (w : ℕ) : Circuit signature (w + w) w :=
  (Circuit.wiring signature (fun i : Fin w => i.castSucc)).comp
    ((carryLookahead w).comp (subtractInputs w))

theorem IsSubformula.of_or_left {N : ℕ} {L R F : PosFormula N}
    (h : PosFormula.IsSubformula (L.or R) F) : PosFormula.IsSubformula L F :=
  (PosFormula.IsSubformula.or_left (.refl L)).trans h

theorem IsSubformula.of_or_right {N : ℕ} {L R F : PosFormula N}
    (h : PosFormula.IsSubformula (L.or R) F) : PosFormula.IsSubformula R F :=
  (PosFormula.IsSubformula.or_right (.refl R)).trans h

theorem IsSubformula.of_and_left {N : ℕ} {L R F : PosFormula N}
    (h : PosFormula.IsSubformula (L.and R) F) : PosFormula.IsSubformula L F :=
  (PosFormula.IsSubformula.and_left (.refl L)).trans h

theorem Circuit.essential_le_depth (c : Circuit σ n m) {I : Interpretation σ U}
    {target : (Fin n → U) → Fin m → U} {selected : Finset (Fin n)} {r : ℕ}
    (hc : c.Computes I target) (h : ∀ k ∈ selected, EssentialAt target k)
    (hr : c.FanInAtMost r) : selected.card ≤ m * max 1 r ^ c.depth :=
  (Finset.card_le_card fun k hk => (h k hk).mem_support hc.dependsOn).trans
    (c.card_inputSupport_le_depth hr)

theorem Formula.Computes.mapOp [φ.Preserves I J] {F : Formula σ n} {f : (Fin n → U) → U}
    (hF : F.Computes I f) : (F.mapOp φ).Computes J f :=
  fun x => (Formula.eval_mapOp F x).trans (hF x)

def specialize (φ : K →+* E) (t : E) :
    MvPolynomial (Fin 3) K →+* MvPolynomial (Fin 2) E :=
  eval₂Hom (MvPolynomial.C.comp φ) (Fin.cases (MvPolynomial.C t) MvPolynomial.X)

private def witnessEmbedding (e : ℕ) : CyclotomicRing.R e →+* WitnessField :=
  (HahnSeries.C : ℂ →+* WitnessField).comp (CyclotomicRing.intoComplex e).toRingHom

/-- Reindex the formula's pencil by its explicit finite dimension. -/

def polynomialMap (M : ℕ) : (Fin M → K) →ₗ[K] K[X] :=
  (Polynomial.degreeLT K M).subtype.comp (Polynomial.degreeLTEquiv K M).symm.toLinearMap

/-- `polynomialMap M` is injective. -/

def replicateScalar (c : Circuit σ n 1) (k : ℕ) : Circuit σ (k * n) k :=
  pi fun j => c.comp (Circuit.wiring σ fun i => finProdFinEquiv (j, i))

/-- Evaluating `c.replicateScalar k` computes `directProduct (fun y => c.eval I y 0) k`. -/

def comp (ψ : τ.Hom υ) (φ : σ.Hom τ) : σ.Hom υ :=
  ⟨ψ ∘ φ, fun op => (ψ.arity_eq (φ op)).trans (φ.arity_eq op)⟩

/-- Applying the identity signature map returns the operation unchanged. -/

def Circuit.withContext (c : Circuit σ n m) (q : ℕ) : Circuit (σ.withContext q) (q + n) m :=
  (c.comp (wiring σ (Fin.natAdd q))).mapLines (Line.withContext q)

/-- Adding context does not add gates or change their costs. -/

theorem Circuit.ComputesFrom.comp {c : Circuit σ n m} {d : Circuit σ m p}
    {f : X → Fin m → U} {g : X → Fin p → U}
    (hc : c.ComputesFrom I f sources) (hd : d.ComputesFrom I g f) :
    (d.comp c).ComputesFrom I g sources := fun x => by
  rw [Circuit.eval_comp, hc x, hd x]

/-- Compute two target families from the same supplied values. -/

theorem IsDense.mono {τ : ℝ} {F F' : Finset (Fin n)} {X : Finset (Fin n → Fin m)}
    (hX : IsDense τ F X) (hF : F' ⊆ F) : IsDense τ F' X :=
  fun I hI => hX I (hI.trans hF)

def step : List (Frame X) × Option ℕ → List (Frame X) × Option ℕ
  | (st, none) =>
    if st.length = D then (st, some (min cap (leaf (history st))))
    else ((first, first, min cap (leaf (history st)), 0) :: st, none)
  | ([], some v) => ([], some v)
  | ((u, w, s, a) :: st, some v) =>
    if last w then
      if last u then (st, some (min cap (s + max a v)))
      else ((next u, first, min cap (s + max a v), 0) :: st, none)
    else ((u, next w, s, max a v) :: st, none)

/-- The number of steps to evaluate a node with `n` rounds to go. -/

theorem IsInteractiveProof.comp {verifier : β → WordOracleComp Operation Bool} {A : Set α}
    {B : Set β} {c s : ENNReal} (h : IsInteractiveProof verifier B c s) {f : α → β}
    (hf : ∀ a, a ∈ A ↔ f a ∈ B) : IsInteractiveProof (fun a => verifier (f a)) A c s where
  complete a ha := h.complete (f a) ((hf a).1 ha)
  sound a ha := h.sound (f a) fun hb => ha ((hf a).2 hb)

/-- **`IP` is closed under polynomial-time reductions.** -/

@[local fun_prop]
private theorem computableTidilyInPolyTime_width {γ : Type} {encIn : γ ↪ List Bool}
    {p : γ → ℕ}
    (hp : ComputableTidilyInPolyTime p encIn encUnary) :
    ComputableTidilyInPolyTime (fun x => width (p x)) encIn encUnary :=
  (ComputableInPolyTime.tidy (computableInPolyTime_width (.of_tidy hp)))

private theorem lt_two_pow_width {a : ℕ} (hp : a < p) : a < 2 ^ width p :=
  hp.trans (Nat.lt_pow_succ_log_self (by norm_num) p)

/-- The rows of the honest encoding of `l` are the bits of its elements. -/

def certDecoder : Decoder encCert :=
  Decoder.list (Decoder.pair Decoder.bits
    (Decoder.list (Decoder.pair Decoder.unary (Decoder.pair Decoder.bits Decoder.bits))))

theorem IsPCPVerifier.mono_randomness {r r' q : ℕ → ℕ} {V : PCPVerifier α} {A : Set α}
    (hr : ∀ n, r n ≤ r' n) (h : IsPCPVerifier enc r q V A) : IsPCPVerifier enc r' q V A :=
  ⟨fun a => (h.1 a).trans (hr _), h.2⟩

theorem computableInPolyTime_splitAlternatingBlocks {γ : Type}
    {encIn : γ ↪ List Bool} (ps : List (Polynomial ℕ × Polynomial ℕ)) {N : γ → ℕ}
    (hN : ComputableInPolyTime N encIn encUnary) {W : γ → List Bool}
    (hW : ComputableInPolyTime W encIn encBits) :
    ComputableInPolyTime
      (fun x => splitAlternatingBlocks (ps.map fun pq => (pq.1.eval (N x), pq.2.eval (N x)))
        (W x)) encIn (encPair encBits encBits) :=
  .of_tidy (computableTidilyInPolyTime_splitAlternatingBlocks ps hN.tidy hW.tidy)

def next (G : Graph) (first : Bool) (vis : List ℕ) (v : ℕ) (bits : List Bool) : Play :=
  if legal G vis v (choice bits) then
    (none, !first, (arc G (choice bits)).2 :: vis, (arc G (choice bits)).2)
  else (some !first, first, vis, v)

/-- **One block of single-bit moves**: a play that is over stays over, and otherwise the player to
move moves by its bits in the block. -/

def lookup (stack : List Frame) (v : ℕ) : Option Bool :=
  (stack.find? (Frame.binds v)).map fun f => f.first.isSome

/-- The assignment of a stack, `false` on the variables it does not bind. -/

def Frame.fields (f : Frame) : (QBF.Kind × ℕ) × Option Bool × List (QBF.Kind × ℕ) :=
  (f.token, f.first, f.rest)

/-- The encoding of the fields of a frame. -/

private def blockEquiv (n : ℕ) : Fin n ⊕ Fin n ≃ Fin (2 * n) :=
  finSumFinEquiv.trans (finCongr (two_mul n).symm)

/-- Combining two permutations $\pi_1, \pi_2 \in S_n$ on the two halves of $\mathrm{Fin}\,(2n)$. -/

private theorem length_le_of_mem_walk (hφ : ∀ c ∈ φ, c.length ≤ k)
    (hw : (rule hK hα).IsNodeWord (rootState hkK φ) w) {C : Clause ℕ}
    (hC : C ∈ ((rule hK hα).walk (rootState hkK φ) w).1) : C.length ≤ k := by
  obtain ⟨D, hD, hCD⟩ := exists_of_mem_walk hK hα hkK hw hC
  rw [← List.toFinset_card_of_nodup (((rule hK hα).walk (rootState hkK φ) w).2.nodup C hC)]
  exact (Finset.card_le_card hCD).trans ((List.toFinset_card_le D).trans (hφ D hD))

private theorem length_encLiteral_le {φ : CNF ℕ} {D : Clause ℕ} (hD : D ∈ φ) {l : Literal ℕ}
    (hl : l ∈ D) : (encPair encNat encBool l).length ≤ (encCNF φ).length :=
  (length_le_encList_of_mem _ hl).trans (length_le_encList_of_mem _ hD)

def literalVertex (φ : CNF ℕ) (l : Literal ℕ) : ℕ :=
  Nat.pair 1 (Nat.pair (φ.vars.idxOf l.1) l.2.toNat)

/-- Vertex `r` of stage `j` of the gadget of clause `i`; vertex `2` is the output of the stage. -/

private theorem snd_mem_SharpP : (Prod.snd : CNF ℕ × ℕ → ℕ) ∈ SharpP (encPair encCNF encNat) :=
  mem_SharpP_of_polyTime (.of_tidy (.snd encCNF encNat))

/-- The number of satisfying assignments of the formula of a pair, as a function in `#P`. -/

def vertexEquiv (G : Graph) : Fin G.distinctVertices.length ≃ {v // v ∈ G.1} :=
  (G.nodup_distinctVertices.getEquiv _).trans
    (Equiv.subtypeEquivRight fun _ => mem_distinctVertices)

def literalVertex (φ : CNF ℕ) (l : Literal ℕ) : ℕ :=
  Nat.pair 0 (Nat.pair (φ.distinctVars.idxOf l.1) l.2.toNat)

/-- The vertex of position `j` of clause `i`. -/

def encMonotoneCircuitValue : (Σ n, Circuit Monotone.signature n 1 × BitString n) ↪ List Bool :=
  ⟨fun x => encCircuitValue (MonotoneCircuitValue.toDeMorgan x),
    encCircuitValue.injective.comp MonotoneCircuitValue.toDeMorgan_injective⟩

private theorem computable_finVal :
    ComputableInPolyTime (fun s : Fin 3 => s.val) (encFinite (Fin 3)) encNat :=
  .of_tidy (ComputableTidilyInPolyTime.of_finite _)

private theorem computable_finVal :
    ComputableInPolyTime (fun s : Fin 3 => s.val) (encFinite (Fin 3)) encNat :=
  .of_tidy (ComputableTidilyInPolyTime.of_finite _)

def encKind : QBF.Kind ↪ List Bool :=
  ⟨fun k => encUnary (kindIndex k), encUnary.injective.comp kindIndex_injective⟩

/-- Tokens encoded as framed pairs of the kind in unary and the variable in binary. -/

def pairSt (st : St) (first : Bool) : St :=
  { st with
    o₁ := if first then st.q₁ else st.q₂
    o₂ := if first then st.q₂ else st.q₁ }

/-- The guess of `ℓ'` in a clause of width two: the first literal, or the second. -/

theorem HardUnder.trans {R : ∀ {α : Type}, (α ↪ List Bool) → P α → Q → Prop}
    {R' : ∀ {α : Type}, (α ↪ List Bool) → P α → Q' → Prop}
    {𝒞 : ∀ {α : Type}, (α ↪ List Bool) → Set (P α)}
    {S : Q → Q' → Prop} {B : Q} {C : Q'}
    (hRS : ∀ {α : Type} (enc : α ↪ List Bool) (A : P α), R enc A B → S B C → R' enc A C)
    (hB : HardUnder @R @𝒞 B) (hBC : S B C) : HardUnder @R' @𝒞 C :=
  fun _ enc A hA => hRS enc A (hB enc A hA) hBC

/-- A weaker reducibility preserves completeness. -/

def pull (c : NativeCertificate f ei em) (other : δ ↪ List Bool) :
    NativeCertificate (fun a : α × δ => f a.1) (encPair ei other) em :=
  c.comp (linear (ComputableInO.fst ei other))

public theorem le_pow (v : α → ℕ) {n : ℕ} (hn : n ≠ 0) : v ≼ fun a => (v a + 1) ^ n :=
  of_le fun _ => (Nat.le_succ _).trans (Nat.le_self_pow hn _)

/-- A bound below a positive power of a larger bound. -/

public theorem fst' {α β₁ β₂ : Type u} {encIn : α ↪ List Bool}
    {enc₁ : β₁ ↪ List Bool} {enc₂ : β₂ ↪ List Bool}
    {f : α → β₁ × β₂} (h : ComputableTidilyInDegree f encIn (encPair enc₁ enc₂) d e) :
    ComputableTidilyInDegree (fun x => (f x).1) encIn enc₁ (max d e) e :=
  ((fst enc₁ enc₂).comp h).mono

/-- The second component of a pair computed with given degrees. -/

public theorem snd' {α β₁ β₂ : Type u} {encIn : α ↪ List Bool}
    {enc₁ : β₁ ↪ List Bool} {enc₂ : β₂ ↪ List Bool}
    {f : α → β₁ × β₂} (h : ComputableTidilyInDegree f encIn (encPair enc₁ enc₂) d e) :
    ComputableTidilyInDegree (fun x => (f x).2) encIn enc₂ (max d e) e :=
  ((snd enc₁ enc₂).comp h).mono

/-- Functions on finite types, in linear time and zero space, with output of constant length. -/

@[fun_prop]
public theorem id' : ComputableTidilyInPolyTime (fun a : α => a) encIn encIn :=
  of_eq fun _ => rfl

@[fun_prop]
public theorem prod {α β₁ β₂ : Type u} {encIn : α ↪ List Bool} {enc₁ : β₁ ↪ List Bool}
    {enc₂ : β₂ ↪ List Bool} {f : α → β₁} {g : α → β₂}
    (hf : ComputableTidilyInPolyTime f encIn enc₁) (hg : ComputableTidilyInPolyTime g encIn enc₂) :
    ComputableTidilyInPolyTime (fun x => (f x, g x)) encIn (encPair enc₁ enc₂) :=
  hf.pair hg

@[fun_prop]
theorem bitsPadWord {α : Type}
    {input : α ↪ List Bool}
    {bound : α → ℕ}
    {word : α → List Bool}
    (hbound : ComputableInPolyTime bound input encUnary)
    (hword : ComputableInPolyTime word input encBits) :
    ComputableInPolyTime
  (fun (a : α) => Cslib.BitString.padWord (bound a) (word a)) input
  encBits :=
  .of_tidy (@Turing.MultiTapeTM.ComputableTidilyInPolyTime.bitsPadWord α input bound word
      hbound.tidy hword.tidy)

/-- Repeat a fixed bit a unary number of times, including zero repetitions. -/

@[fun_prop]
theorem anyWithInput {α : Type}
    {γ : Type}
    {encA : α ↪ List Bool}
    {encIn : γ ↪ List Bool}
    {test : γ → α → Bool}
    {list : γ → List α}
    (hlist : ComputableInPolyTime list encIn (encList encA))
    (htest : ComputableInPolyTime (fun (p : γ × α) => test p.1 p.2)
  (encPair encIn encA) encBool) :
    ComputableInPolyTime (fun (x : γ) => (list x).any (test x)) encIn
  encBool :=
  .of_tidy (@Turing.MultiTapeTM.ComputableTidilyInPolyTime.anyWithInput α γ encA encIn test list
      hlist.tidy htest.tidy)

/-- Concatenate raw bit strings, charging for both computed words. -/

@[fun_prop]
theorem bitsAppend {γ : Type}
    {encIn : γ ↪ List Bool}
    {left : γ → List Bool}
    {right : γ → List Bool}
    (hleft : ComputableInPolyTime left encIn encBits)
    (hright : ComputableInPolyTime right encIn encBits) :
    ComputableInPolyTime (fun (x : γ) => left x ++ right x) encIn
  encBits :=
  .of_tidy (@Turing.MultiTapeTM.ComputableTidilyInPolyTime.bitsAppend γ encIn left right
      hleft.tidy hright.tidy)

/-- Take a computed unary number of bits from a computed bit string. -/

@[fun_prop]
theorem bitsTakeWithInput {γ : Type}
    {encIn : γ ↪ List Bool}
    {list : γ → List Bool}
    {count : γ → ℕ}
    (hlist : ComputableInPolyTime list encIn encBits)
    (hcount : ComputableInPolyTime count encIn encUnary) :
    ComputableInPolyTime (fun (x : γ) => List.take (count x) (list x))
  encIn encBits :=
  .of_tidy (@Turing.MultiTapeTM.ComputableTidilyInPolyTime.bitsTakeWithInput γ encIn list count
      hlist.tidy hcount.tidy)

/-- The encoded input length, computed in unary by reading the input word. -/

@[fun_prop]
theorem filterWithInput {α : Type}
    {γ : Type}
    {encA : α ↪ List Bool}
    {encIn : γ ↪ List Bool}
    {test : γ → α → Bool}
    {list : γ → List α}
    (hlist : ComputableInPolyTime list encIn (encList encA))
    (htest : ComputableInPolyTime (fun (p : γ × α) => test p.1 p.2)
  (encPair encIn encA) encBool) :
    ComputableInPolyTime (fun (x : γ) => List.filter (test x) (list x))
  encIn (encList encA) :=
  .of_tidy (@Turing.MultiTapeTM.ComputableTidilyInPolyTime.filterWithInput α γ encA encIn test
      list hlist.tidy htest.tidy)

/-- Concatenate lists computed jointly from the original input and each list element.
Like `mapWithInput`, this is a composition rule for `fun_prop`. -/

@[fun_prop]
theorem flatMapWithInput {α : Type}
    {β : Type}
    {γ : Type}
    {encA : α ↪ List Bool}
    {encB : β ↪ List Bool}
    {encIn : γ ↪ List Bool}
    {f : γ → α → List β}
    {list : γ → List α}
    (hlist : ComputableInPolyTime list encIn (encList encA))
    (hf : ComputableInPolyTime (fun (p : γ × α) => f p.1 p.2)
  (encPair encIn encA) (encList encB)) :
