variable {ι σ α : Type} {spec : ι → Type} {first second : (q : ι) → StateT σ PMF (spec q)}
  {bad : σ → Prop}

/-- **The difference lemma** ([BonehShoup2023], Theorem 4.7): games that run a program against
handlers agreeing until a bad state, followed by the same final step, have advantage at most the
probability of reaching a bad state. -/

def feistel3 (f₁ f₂ f₃ : G → G) : G × G ≃ G × G :=
  (feistelRoundEquiv f₁).trans ((feistelRoundEquiv f₂).trans (feistelRoundEquiv f₃))

/-- The four-round Feistel permutation `(feistel3 f₁ f₂ f₃).trans (feistelRoundEquiv f₄)`. -/

private theorem extractInput_decoder :
    ∃ D : Decoder encLyubashevskyExtractInput, D.decode = decodeLyubashevskyExtractInput := by
  let integer : Decoder encIntBin := {
    decode := decodeIntBin
    decode_enc := decodeIntBin_encIntBin
    computable := computableInPolyTime_decodeIntBin.exists_degree }
  let row := Decoder.pair Decoder.bits (Decoder.option (Decoder.list integer))
  let decoder := Decoder.pair (Decoder.pair Decoder.unary Decoder.unary) (Decoder.pair row row)
  exact ⟨decoder, rfl⟩

